  function lineHtml(){const items=arr("items").filter(x=>x.active&&x.tracking_mode==="quantity");return `<div class="int-line"><label>Article<select data-line-item required><option value="">Choisir…</option>${options(items)}</select></label><label>Unité<select data-line-unit required><option value="">Choisir l’article</option></select></label><label>Quantité<input data-line-qty type="number" min="1" step="1" value="1" required></label><button type="button" data-remove-line aria-label="Retirer">×</button></div>`;}
  function syncLineUnits(line){const itemId=$("[data-line-item]",line).value;const units=itemUnits(itemId);const select=$("[data-line-unit]",line);select.innerHTML=options(units,"unit_id","unit_id");[...select.options].forEach(o=>{o.textContent=unitName(o.value);});const preferred=units.find(x=>x.is_default_purchase)||units.find(x=>x.is_default_issue)||units[0];if(preferred)select.value=preferred.unit_id;}
  function openMovement(type){
    const receipt=type==="receipt",locations=arr("locations").filter(x=>x.active);if(!arr("items").some(x=>x.tracking_mode==="quantity")||!locations.length){ctx.showToast("Créez d’abord un article et un local");return;}
    openDialog({title:receipt?"Nouvelle entrée":"Nouvelle sortie",kicker:"Mouvement de stock",submit:receipt?"Valider l’entrée":"Valider la sortie",body:`<div class="int-form-grid"><label>Type<select id="int-movement-type">${(receipt?[["receipt","Réception"],["opening","Stock initial"],["adjustment_in","Correction positive"]]:[["issue","Sortie"],["transfer","Transfert"],["adjustment_out","Correction négative"]]).map(x=>`<option value="${x[0]}">${x[1]}</option>`).join("")}</select></label><label>Date<input id="int-movement-date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label id="int-source-wrap" ${receipt?"hidden":""}>Local source<select id="int-movement-source"><option value="">Choisir…</option>${options(locations)}</select></label><label id="int-dest-wrap" ${receipt?"":"hidden"}>Local destination<select id="int-movement-dest"><option value="">Choisir…</option>${options(locations)}</select></label><label>Bénéficiaire / remis à<input id="int-movement-recipient"></label><label>Référence<input id="int-movement-reference" placeholder="Facture, bon…"></label><label class="wide" id="int-reason-wrap" hidden>Motif de correction<input id="int-movement-reason"></label></div><div class="int-line-editor" id="int-lines">${lineHtml()}</div><button type="button" class="int-add-line" id="int-add-line">+ Ajouter une ligne</button><p class="privacy-note">Sans connexion, cette opération restera sur cet appareil avec une clé unique puis sera synchronisée sans doublon.</p>`,onSubmit:async()=>{const movement=formValue("#int-movement-type");const lines=$$(".int-line",$("#int-lines")).map(line=>({item_id:$("[data-line-item]",line).value,unit_id:$("[data-line-unit]",line).value,quantity:Number($("[data-line-qty]",line).value)}));await recordMovement({p_school_id:schoolId(),p_movement_type:movement,p_document_date:formValue("#int-movement-date"),p_source_location_id:formValue("#int-movement-source"),p_destination_location_id:formValue("#int-movement-dest"),p_partner_id:null,p_recipient_name:formValue("#int-movement-recipient"),p_reference:formValue("#int-movement-reference"),p_reason:formValue("#int-movement-reason"),p_notes:null,p_lines:lines});}});
    const body=$("#intendance-dialog-body");syncLineUnits($(".int-line",body));$("#int-add-line",body).addEventListener("click",()=>{$("#int-lines",body).insertAdjacentHTML("beforeend",lineHtml());syncLineUnits($$(".int-line",body).at(-1));});body.addEventListener("change",e=>{if(e.target.matches("[data-line-item]"))syncLineUnits(e.target.closest(".int-line"));if(e.target.id==="int-movement-type"){const v=e.target.value,$s=$("#int-source-wrap"),$d=$("#int-dest-wrap"),$r=$("#int-reason-wrap");$s.hidden=!["issue","transfer","adjustment_out"].includes(v);$d.hidden=!["receipt","opening","adjustment_in","transfer"].includes(v);$r.hidden=!v.startsWith("adjustment_");}});body.addEventListener("click",e=>{const b=e.target.closest("[data-remove-line]");if(b&&$$(".int-line",body).length>1)b.closest(".int-line").remove();});
  }
  function openAsset(assetId=null){const existing=assetId?byId("assets",assetId):null,items=arr("items").filter(x=>x.active&&x.tracking_mode==="asset");if(!items.length){ctx.showToast("Créez d’abord un article suivi comme patrimoine");return;}openDialog({title:existing?"Gérer le bien":"Nouveau bien",kicker:"Patrimoine",submit:"Enregistrer",body:`<div class="int-form-grid"><label>Type de bien<select id="int-asset-item">${options(items,"id","name",existing?.item_id)}</select></label><label>Étiquette patrimoniale<input id="int-asset-tag" value="${h(existing?.asset_tag||"")}" placeholder="Automatique si vide"></label><label>N° de série<input id="int-asset-serial" value="${h(existing?.serial_number||"")}"></label><label>Date d’acquisition<input id="int-asset-date" type="date" value="${h(existing?.acquisition_date||"")}"></label><label>Valeur d’acquisition<input id="int-asset-cost" type="number" min="0" step="0.01" value="${h(existing?.acquisition_cost||"")}"></label><label>Local<select id="int-asset-location"><option value="">Non affecté</option>${options(arr("locations").filter(x=>x.active),"id","name",existing?.location_id)}</select></label><label>État physique<select id="int-asset-condition">${["new","good","fair","poor","out_of_service","disposed"].map(x=>`<option value="${x}" ${existing?.condition===x?"selected":""}>${label[x]}</option>`).join("")}</select></label><label>Statut<select id="int-asset-state">${["in_stock","assigned","maintenance","lost","disposed"].map(x=>`<option value="${x}" ${existing?.status===x?"selected":""}>${label[x]}</option>`).join("")}</select></label><label class="wide">Notes<textarea id="int-asset-notes">${h(existing?.notes||"")}</textarea></label></div>`,onSubmit:async()=>rpc("save_intendance_asset",{p_school_id:schoolId(),p_asset_id:assetId,p_item_id:formValue("#int-asset-item"),p_asset_tag:formValue("#int-asset-tag")||"",p_serial_number:formValue("#int-asset-serial"),p_acquisition_date:formValue("#int-asset-date"),p_acquisition_cost:formValue("#int-asset-cost")?Number(formValue("#int-asset-cost")):null,p_condition:formValue("#int-asset-condition"),p_status:formValue("#int-asset-state"),p_location_id:formValue("#int-asset-location"),p_custodian_user_id:null,p_notes:formValue("#int-asset-notes")},"Patrimoine mis à jour")});}
  function openReference(type){const config={location:["Nouveau local","intendance_locations",`<label>Code<input id="ref-code" required></label><label>Nom<input id="ref-name" required></label><label>Type<select id="ref-type">${Object.entries(locationTypeLabel).map(([value,text])=>`<option value="${value}">${text}</option>`).join("")}</select></label>`],category:["Nouvelle catégorie","intendance_categories",`<label>Code<input id="ref-code" required></label><label>Nom<input id="ref-name" required></label><label>Type<select id="ref-type">${Object.entries(itemTypeLabel).map(([value,text])=>`<option value="${value}">${text}</option>`).join("")}</select></label>`],unit:["Nouvelle unité","intendance_units",`<label>Code<input id="ref-code" required></label><label>Nom<input id="ref-name" required></label><label>Symbole<input id="ref-symbol" required></label>`],partner:["Nouveau partenaire","intendance_partners",`<label>Nom<input id="ref-name" required></label><label>Type<select id="ref-type">${Object.entries(partnerTypeLabel).map(([value,text])=>`<option value="${value}">${text}</option>`).join("")}</select></label><label>Téléphone<input id="ref-phone"></label>`]}[type];if(!config)return;openDialog({title:config[0],kicker:"Référentiels",body:`<div class="int-form-grid">${config[2]}</div>`,onSubmit:async()=>{const row={school_id:schoolId(),name:formValue("#ref-name"),active:true,created_by:ctx.state.profile.id};if(type!=="partner")row.code=formValue("#ref-code")?.toUpperCase();if(type==="location")row.location_type=formValue("#ref-type");if(type==="category")row.category_type=formValue("#ref-type");if(type==="unit")row.symbol=formValue("#ref-symbol");if(type==="partner"){row.partner_type=formValue("#ref-type");row.phone=formValue("#ref-phone");}const {error}=await ctx.state.client.from(config[1]).insert(row);if(error)throw error;await refresh("Référence ajoutée");}});}
  function openInventory(){const locations=arr("locations").filter(x=>x.active);openDialog({title:"Démarrer un inventaire",kicker:"Comptage physique",submit:"Créer la feuille de comptage",body:`<div class="int-form-grid"><label>Local à inventorier<select id="int-inventory-location">${options(locations)}</select></label><label>Notes<input id="int-inventory-notes"></label></div>`,onSubmit:async()=>rpc("start_intendance_inventory",{p_school_id:schoolId(),p_location_id:formValue("#int-inventory-location"),p_notes:formValue("#int-inventory-notes")},"Inventaire démarré")});}
  function countInventory(id){const inv=arr("inventories").find(x=>x.id===id);if(!inv)return;openDialog({title:inv.inventory_number,kicker:`Comptage · ${locationName(inv.location_id)}`,submit:"Valider et comptabiliser",body:`<div class="int-line-editor">${(inv.lines||[]).map(line=>`<div class="int-line"><label>${h(itemName(line.item_id))}<small>Attendu : ${h(formatQuantity(line.item_id,line.expected_base))}</small></label><label>Quantité comptée (base)<input data-count-item="${line.item_id}" type="number" min="0" step="1" value="${h(line.counted_base??line.expected_base)}" required></label><label>Unité<output>${h(unitName(byId("items",line.item_id)?.base_unit_id))}</output></label></div>`).join("")}</div><p class="privacy-note">La validation comptabilise les écarts dans le registre de stock.</p>`,onSubmit:async()=>{const counts=$$("[data-count-item]",$("#intendance-dialog-body")).map(input=>({item_id:input.dataset.countItem,counted_base:Number(input.value),notes:null}));await rpc("post_intendance_inventory",{p_inventory_id:id,p_counts:counts},"Inventaire comptabilisé");}});}
  function openEditItem(id){const item=byId("items",id);if(!item)return;openDialog({title:`Modifier ${item.name}`,kicker:"Catalogue",submit:"Enregistrer les modifications",body:`<div class="int-form-grid"><label>Code interne<output class="int-readonly-code">${h(item.sku)}</output></label><label>Désignation<input id="int-edit-name" value="${h(item.name)}" required></label><label>Catégorie<select id="int-edit-category">${options(arr("categories").filter(x=>x.active),"id","name",item.category_id)}</select></label><label>Type<select id="int-edit-type">${Object.entries(itemTypeLabel).map(([value,text])=>`<option value="${value}" ${item.item_type===value?"selected":""}>${text}</option>`).join("")}</select></label><label>Seuil minimum (base)<input id="int-edit-min" type="number" min="0" step="1" value="${h(item.minimum_stock_base)}"></label><label>Stock cible (base)<input id="int-edit-target" type="number" min="0" step="1" value="${h(item.reorder_target_base)}"></label><label class="wide">Notes<textarea id="int-edit-notes">${h(item.notes||"")}</textarea></label><label class="wide int-checkbox"><input id="int-edit-active" type="checkbox" ${item.active?"checked":""}> Article actif</label></div><p class="privacy-note">Le code interne, l’unité de base et les conversions restent verrouillés afin de préserver l’historique exact.</p>`,onSubmit:async()=>rpc("update_intendance_item",{p_item_id:id,p_sku:null,p_name:formValue("#int-edit-name"),p_category_id:formValue("#int-edit-category"),p_item_type:formValue("#int-edit-type"),p_minimum_stock_base:Number(formValue("#int-edit-min")||0),p_reorder_target_base:Number(formValue("#int-edit-target")||0),p_notes:formValue("#int-edit-notes"),p_active:$("#int-edit-active").checked},"Article mis à jour")});}
  function detailItem(id){const item=byId("items",id),q=totalStock(id);if(!item)return;openDialog({title:item.name,kicker:item.sku,submit:canWrite()?"Modifier l’article":"Fermer",body:`<div class="int-summary-box"><div><strong>${h(formatQuantity(id,q))}</strong><small>Stock total</small></div><div><strong>${h(formatQuantity(id,item.minimum_stock_base))}</strong><small>Seuil minimum</small></div><div><strong>${h(formatQuantity(id,item.reorder_target_base))}</strong><small>Stock cible</small></div></div><div class="int-table-wrap" style="margin-top:14px"><table class="int-table"><thead><tr><th>Local</th><th>Quantité exacte</th></tr></thead><tbody>${arr("stock").filter(x=>x.item_id===id).map(x=>`<tr><td>${h(locationName(x.location_id))}</td><td>${h(formatQuantity(id,x.quantity_base))}</td></tr>`).join("")||'<tr><td colspan="2">Aucun stock</td></tr>'}</tbody></table></div>`,onSubmit:async()=>{if(canWrite())setTimeout(()=>openEditItem(id),0);return true;}});}

  function exportStock(){const rows=[["Code","Article","Catégorie","Local","Quantité base","Affichage"]];for(const item of arr("items").filter(x=>x.tracking_mode==="quantity")){const balances=arr("stock").filter(x=>x.item_id===item.id);if(!balances.length)rows.push([item.sku,item.name,byId("categories",item.category_id)?.name||"","",0,formatQuantity(item.id,0)]);for(const b of balances)rows.push([item.sku,item.name,byId("categories",item.category_id)?.name||"",locationName(b.location_id),b.quantity_base,formatQuantity(item.id,b.quantity_base)]);}download(`stock-${ctx.state.school?.short_name||"ecole"}-${new Date().toISOString().slice(0,10)}.csv`,`\ufeff${rows.map(r=>r.map(csvCell).join(";")).join("\n")}`);}
  function exportMovements(){const rows=[["Document","Date","Type","État","Article","Quantité","Unité","Multiplicateur","Quantité base","Bénéficiaire"]];for(const d of arr("documents"))for(const l of d.lines||[])rows.push([d.document_number,d.document_date,label[d.movement_type]||d.movement_type,label[d.status]||d.status,itemName(l.item_id),l.quantity_in_unit,unitName(l.unit_id),l.multiplier_to_base,l.quantity_base,d.recipient_name||""]);download(`mouvements-${ctx.state.school?.short_name||"ecole"}.csv`,`\ufeff${rows.map(r=>r.map(csvCell).join(";")).join("\n")}`);}
  function exportForecast(){const rows=[["Code","Article","Stock actuel","Stock cible","À prévoir"]];for(const i of arr("items").filter(x=>x.tracking_mode==="quantity")){const q=totalStock(i.id),target=toBig(i.reorder_target_base),need=target>q?target-q:0n;if(need>0n)rows.push([i.sku,i.name,formatQuantity(i.id,q),formatQuantity(i.id,target),formatQuantity(i.id,need)]);}download("previsions-reapprovisionnement.csv",`\ufeff${rows.map(r=>r.map(csvCell).join(";")).join("\n")}`);}
  function cancelDocument(id){openDialog({title:"Annuler le mouvement",kicker:"Contre-écriture sécurisée",submit:"Confirmer l’annulation",body:'<label>Motif obligatoire<textarea id="int-cancel-reason" rows="3" required></textarea></label><p class="privacy-note">Le registre original sera conservé et une contre-écriture sera créée.</p>',onSubmit:async()=>rpc("cancel_intendance_document",{p_document_id:id,p_reason:formValue("#int-cancel-reason")},"Document annulé")});}
